"use client";
import React, { useState, useEffect, useRef } from "react";
import Link from "next/link";

const C={navy:"#0B1D3A",navyMid:"#0F2847",card:"#0D2240",cardHover:"#112A4D",blue:"#2D7FF9",teal:"#00C9A7",red:"#EF4343",amber:"#F59E0B",purple:"#8B5CF6",slate:"#94A3B8",slateLight:"#CBD5E1",white:"#FFFFFF",border:"#1E3A5F"};
const FH=`'Outfit',sans-serif`,FB=`'DM Sans',sans-serif`,FM=`'JetBrains Mono',monospace`;

const CSS=`@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800;900&family=DM+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=JetBrains+Mono:wght@400;500&display=swap');
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}html{scroll-behavior:smooth;-webkit-font-smoothing:antialiased}
body{background:${C.navy};color:${C.slateLight};font-family:${FB};line-height:1.6;overflow-x:hidden}
::selection{background:${C.teal}33;color:${C.white}}
@keyframes su{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:translateY(0)}}
@keyframes bk{0%,50%{border-color:${C.teal}}51%,100%{border-color:transparent}}
@keyframes pg{0%,100%{opacity:.4}50%{opacity:.9}}
@keyframes mq{from{transform:translateX(0)}to{transform:translateX(-50%)}}
@keyframes fd{from{stroke-dashoffset:20}to{stroke-dashoffset:0}}
@keyframes float1{0%,100%{transform:translateY(0) translateX(0)}25%{transform:translateY(-20px) translateX(10px)}50%{transform:translateY(-10px) translateX(-8px)}75%{transform:translateY(-25px) translateX(5px)}}
@keyframes float2{0%,100%{transform:translateY(0) translateX(0)}33%{transform:translateY(-15px) translateX(-12px)}66%{transform:translateY(-8px) translateX(15px)}}
@keyframes float3{0%,100%{transform:translateY(0)}50%{transform:translateY(-18px)}}
@keyframes gradShift{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}
.gt{background:linear-gradient(135deg,${C.teal},${C.blue});-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.gta{background:linear-gradient(135deg,${C.amber},${C.red});-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.gb{background:linear-gradient(135deg,${C.teal},${C.blue});color:${C.white};border:none;cursor:pointer;transition:all .3s}
.gb:hover{transform:translateY(-2px);box-shadow:0 8px 30px ${C.teal}44}
.ob{background:transparent;color:${C.white};border:1px solid ${C.border};cursor:pointer;transition:all .3s}
.ob:hover{border-color:${C.teal};background:${C.teal}11}
::-webkit-scrollbar{width:6px}::-webkit-scrollbar-track{background:${C.navy}}::-webkit-scrollbar-thumb{background:${C.border};border-radius:3px}`;

function Sty(){useEffect(()=>{if(!document.getElementById("sd")){const s=document.createElement("style");s.id="sd";s.textContent=CSS;document.head.appendChild(s)}},[]);return null}

function CursorGlow(){const[pos,setPos]=useState({x:-100,y:-100});const{mob}=useMedia();useEffect(()=>{if(mob)return;const h=e=>setPos({x:e.clientX,y:e.clientY});window.addEventListener("mousemove",h);return()=>window.removeEventListener("mousemove",h)},[mob]);if(mob)return null;return(<div style={{position:"fixed",left:pos.x-150,top:pos.y-150,width:300,height:300,borderRadius:"50%",background:`radial-gradient(circle,${C.teal}12 0%,${C.blue}08 40%,transparent 70%)`,pointerEvents:"none",zIndex:9999,transition:"left .15s ease-out, top .15s ease-out",filter:"blur(2px)"}}/>)}

function Particles(){const dots=[{x:"10%",y:"20%",s:3,d:"8s",a:"float1",o:.15},{x:"85%",y:"15%",s:4,d:"12s",a:"float2",o:.1},{x:"20%",y:"60%",s:2,d:"10s",a:"float3",o:.12},{x:"70%",y:"45%",s:3,d:"9s",a:"float1",o:.08},{x:"50%",y:"80%",s:2,d:"11s",a:"float2",o:.1},{x:"90%",y:"70%",s:3,d:"7s",a:"float3",o:.12},{x:"35%",y:"30%",s:2,d:"13s",a:"float1",o:.06},{x:"60%",y:"90%",s:4,d:"10s",a:"float2",o:.08}];return(<div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:1,overflow:"hidden"}}>{dots.map((d,i)=>(<div key={i} style={{position:"absolute",left:d.x,top:d.y,width:d.s,height:d.s,borderRadius:"50%",background:i%2===0?C.teal:C.blue,opacity:d.o,animation:`${d.a} ${d.d} ease-in-out infinite`,animationDelay:`${i*0.7}s`}}/>))}</div>)}

function FlowingBG(){const[scrollY,setScrollY]=useState(0);const[pageH,setPageH]=useState(6000);useEffect(()=>{setPageH(document.documentElement.scrollHeight);const h=()=>setScrollY(window.scrollY);window.addEventListener("scroll",h,{passive:true});return()=>window.removeEventListener("scroll",h)},[]);const pct=Math.min(scrollY/Math.max(pageH-( typeof window!=="undefined"?window.innerHeight:900),1),1);return(<div style={{position:"fixed",inset:0,zIndex:0,pointerEvents:"none"}}><div style={{position:"absolute",inset:0,background:`radial-gradient(ellipse 80% 50% at ${20+pct*30}% ${30+pct*40}%,${C.teal}16 0%,transparent 70%),radial-gradient(ellipse 60% 70% at ${70-pct*20}% ${20+pct*50}%,${C.blue}14 0%,transparent 60%),radial-gradient(ellipse 50% 40% at ${50+pct*15}% ${60-pct*20}%,${C.purple}0A 0%,transparent 50%),radial-gradient(ellipse 40% 30% at ${30-pct*10}% ${80-pct*30}%,${C.teal}0C 0%,transparent 40%)`,transition:"background .3s ease-out"}}/><div style={{position:"absolute",inset:0,opacity:.015,backgroundImage:`url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")`,backgroundSize:"128px 128px"}}/></div>)}

function useMedia(){const[w,sW]=useState(1200);useEffect(()=>{sW(window.innerWidth);const h=()=>sW(window.innerWidth);window.addEventListener("resize",h);return()=>window.removeEventListener("resize",h)},[]);return{w,mob:w<768,tab:w>=768&&w<1024,desk:w>=1024}}
function useR(t=.08){const r=useRef(null),[v,s]=useState(false);useEffect(()=>{const el=r.current;if(!el)return;const o=new IntersectionObserver(([e])=>{if(e.isIntersecting){s(true);o.disconnect()}},{threshold:t});o.observe(el);return()=>o.disconnect()},[t]);return[r,v]}
function Rev({children,delay=0,y=28,style={}}){const[r,v]=useR();return(<div ref={r} style={{opacity:v?1:0,transform:v?"none":`translateY(${y}px)`,transition:`opacity .7s cubic-bezier(.22,1,.36,1) ${delay}s, transform .7s cubic-bezier(.22,1,.36,1) ${delay}s`,...style}}>{children}</div>)}

/* ─── Typewriter with variable speed ─── */
function TW({text,speed=12,trigger=true}){const[d,sD]=useState("");const cancelRef=useRef({cancelled:false});useEffect(()=>{cancelRef.current.cancelled=true;cancelRef.current={cancelled:false};const local=cancelRef.current;let i=0;sD("");const chars=text.split("");const tick=()=>{if(local.cancelled)return;if(i>=chars.length)return;i+=2;sD(chars.slice(0,i).join(""));const ch=chars[i-1];const delay=ch==="\n"?80:ch==="."||ch==="!"?40:speed;setTimeout(tick,delay)};if(trigger)setTimeout(tick,120);return()=>{local.cancelled=true}},[text,trigger,speed]);return(<span>{d}<span style={{borderRight:`2px solid ${C.teal}`,animation:"bk 1s infinite",marginLeft:1}}>&nbsp;</span></span>)}

