function Why(){const{mob}=useMedia();const layers=["Org Structure","Capability Library","Team Intel","Public Intelligence"];const bs=[{ic:Ic.bolt,t:"Hyper-Personalised Collateral",d:"AI drafts emails, briefs, and decks using stakeholder role and real account initiatives."},{ic:Ic.target,t:"AI Opportunity Discovery",d:"Cross-references capabilities against initiatives to surface hidden opportunities."},{ic:Ic.brain,t:"Contextual Recommendations",d:"Who to contact, which capability to lead with, which champion opens the door."},{ic:Ic.shield,t:"Institutional Memory",d:"Meeting notes and relationship history survive rep transitions."},{ic:Ic.search,t:"Gap Analysis",d:"Buying committee, engagement, and capability gaps — visible with AI plays."},{ic:Ic.chart,t:"Financially-Aware Engagement",d:"Revenue trends and pipeline data flow into every AI interaction."}];return(
<section id="why" style={{padding:mob?"60px 20px":"100px 24px"}}><div style={{maxWidth:1400,margin:"0 auto"}}><Rev><div style={{textAlign:"center",marginBottom:mob?32:48}}><span style={{fontSize:11,fontWeight:700,letterSpacing:".18em",textTransform:"uppercase",color:C.teal}}>Why SalesDendrite</span><h2 style={{fontFamily:FH,fontWeight:800,fontSize:mob?26:42,color:C.white,marginTop:12}}>Four data layers converge into execution.</h2></div></Rev>{!mob&&<Rev delay={.1}><div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:10,flexWrap:"wrap",marginBottom:56,padding:"20px 0"}}>{layers.map((l,i)=>(<React.Fragment key={l}><span style={{fontFamily:FM,fontSize:12,color:C.teal,background:C.teal+"12",border:`1px solid ${C.teal}33`,borderRadius:8,padding:"7px 14px"}}>{l}</span>{i<3&&<span style={{color:C.slate}}>+</span>}</React.Fragment>))}<span style={{color:C.teal,fontSize:18,margin:"0 6px"}}>→</span><span style={{fontFamily:FH,fontWeight:800,fontSize:14,background:`linear-gradient(135deg,${C.teal},${C.blue})`,color:C.navy,borderRadius:8,padding:"9px 18px"}}>Execution Intelligence</span></div></Rev>}<div style={{display:"grid",gridTemplateColumns:mob?"1fr":"repeat(3,1fr)",gap:mob?14:20}}>{bs.map((b,i)=>(<Rev key={i} delay={i*.06} style={{height:"100%"}}><div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:mob?"20px":"26px 22px",transition:"all .3s",height:"100%"}} onMouseEnter={e=>{e.currentTarget.style.borderColor=C.teal+"44"}} onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border}}><div style={{marginBottom:8}}>{b.ic(C.teal)}</div><h3 style={{fontFamily:FH,fontWeight:700,fontSize:mob?14:15,color:C.white,marginBottom:5}}>{b.t}</h3><p style={{fontSize:mob?12:13,color:C.slate,lineHeight:1.7}}>{b.d}</p></div></Rev>))}</div></div></section>)}

