function Carousel(){const[p,sP]=useState(false);const items=["Salesforce","HubSpot","Veeva CRM","Dynamics 365","Google Drive","SharePoint","Confluence","Notion","Slack","Microsoft Teams","SEC Edgar","ClinicalTrials.gov"];return(<section style={{padding:"50px 0",overflow:"hidden"}}><Rev><p style={{textAlign:"center",fontSize:11,fontWeight:600,letterSpacing:".15em",textTransform:"uppercase",color:C.slate,marginBottom:20}}>Connects with your stack</p></Rev><div onMouseEnter={()=>sP(true)} onMouseLeave={()=>sP(false)} style={{display:"flex",animation:"mq 30s linear infinite",animationPlayState:p?"paused":"running",width:"fit-content"}}>{[...items,...items].map((n,i)=>(<div key={i} style={{flexShrink:0,padding:"8px 20px",margin:"0 5px",background:C.card,border:`1px solid ${C.border}`,borderRadius:6,fontFamily:FM,fontSize:11,color:C.slate,fontWeight:500,whiteSpace:"nowrap",transition:"all .3s"}} onMouseEnter={e=>{e.currentTarget.style.color=C.teal}} onMouseLeave={e=>{e.currentTarget.style.color=C.slate}}>{n}</div>))}</div></section>)}

