function Compare(){const{mob}=useMedia();const[hov,setHov]=useState(null);const fs=[{n:"Contact database",sd:1,ci:1,ri:1,rf:1},{n:"Org hierarchy mapping",sd:1,ci:0,ri:0,rf:0},{n:"AI email generation",sd:1,ci:0,ri:1,rf:0},{n:"Buying committee mapping",sd:1,ci:0,ri:0,rf:0},{n:"Account financial intelligence",sd:1,ci:0,ri:0,rf:1},{n:"AI pre-call briefs",sd:1,ci:0,ri:1,rf:0},{n:"Stakeholder conversion strategies",sd:1,ci:0,ri:0,rf:0},{n:"Capability-to-need matching",sd:1,ci:0,ri:0,rf:0},{n:"Full context AI workspace",sd:1,ci:0,ri:0,rf:0}];const Y=()=><span style={{color:C.teal,fontSize:14}}>✓</span>;const N=()=><span style={{color:C.border}}>—</span>;return(
<section style={{padding:mob?"60px 20px":"80px 24px",maxWidth:900,margin:"0 auto"}}><Rev><div style={{textAlign:"center",marginBottom:mob?32:48}}><span style={{fontSize:11,fontWeight:700,letterSpacing:".18em",textTransform:"uppercase",color:C.teal}}>How We Compare</span><h2 style={{fontFamily:FH,fontWeight:800,fontSize:mob?24:36,color:C.white,marginTop:12}}>Built for sales execution intelligence.</h2></div></Rev><Rev delay={.1}><div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:"auto",WebkitOverflowScrolling:"touch"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:mob?11:13,minWidth:mob?500:"auto"}}><thead><tr style={{borderBottom:`1px solid ${C.border}`}}><th style={{padding:mob?"10px 12px":"14px 18px",textAlign:"left",color:C.slate,fontWeight:500}}>Feature</th><th style={{padding:"10px 8px",textAlign:"center",width:mob?70:95}}><span className="gt" style={{fontFamily:FH,fontWeight:700,fontSize:mob?11:13}}>SalesDendrite</span></th><th style={{padding:"10px 8px",textAlign:"center",color:C.slate,fontWeight:500,width:mob?60:90}}>Contact Intel Tools</th><th style={{padding:"10px 8px",textAlign:"center",color:C.slate,fontWeight:500,width:mob?60:90}}>Revenue Intel Tools</th><th style={{padding:"10px 8px",textAlign:"center",color:C.slate,fontWeight:500,width:mob?60:90}}>Revenue Forecasting</th></tr></thead><tbody>{fs.map((f,i)=>(<tr key={i} onMouseEnter={()=>setHov(i)} onMouseLeave={()=>setHov(null)} style={{borderBottom:i<fs.length-1?`1px solid ${C.border}44`:"none",background:hov===i?C.cardHover:i%2===0?"transparent":C.navyMid+"44",transition:"background .2s"}}><td style={{padding:mob?"8px 12px":"11px 18px",color:hov===i?C.white:C.slateLight,fontWeight:500}}>{f.n}</td><td style={{textAlign:"center",background:C.teal+"08"}}>{f.sd?<Y/>:<N/>}</td><td style={{textAlign:"center"}}>{f.ci?<Y/>:<N/>}</td><td style={{textAlign:"center"}}>{f.ri?<Y/>:<N/>}</td><td style={{textAlign:"center"}}>{f.rf?<Y/>:<N/>}</td></tr>))}</tbody></table></div></Rev></section>)}

/* ═══════════ CONTACT ═══════════ */
function Contact(){const[f,sF]=useState({name:"",email:"",company:"",message:""});const[done,setDone]=useState(false);const[sending,setSending]=useState(false);const[foc,sFoc]=useState(null);const{mob}=useMedia();const ip=k=>({width:"100%",padding:mob?"10px 14px":"12px 16px",background:C.navyMid,border:`1px solid ${foc===k?C.teal:C.border}`,borderRadius:8,color:C.white,fontSize:14,fontFamily:FB,outline:"none",transition:"border-color .2s"});const handleSubmit=async(e)=>{e.preventDefault();if(!f.name||!f.email||!f.company)return;setSending(true);try{await fetch("/",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({"form-name":"contact",...f}).toString()});setDone(true)}catch(err){setDone(true)}setSending(false)};return(
<section id="contact" style={{padding:mob?"60px 20px":"100px 24px"}}><div style={{maxWidth:560,margin:"0 auto",textAlign:"center"}}><Rev><h2 style={{fontFamily:FH,fontWeight:800,fontSize:mob?28:42,color:C.white,marginBottom:12}}>Let's put this on your account.</h2><p style={{fontSize:mob?14:16,color:C.slate,marginBottom:32,lineHeight:1.7}}>Pick one account. Upload the org chart. Let the platform do its thing.</p></Rev>{done?(<Rev><div style={{background:C.teal+"15",border:`1px solid ${C.teal}44`,borderRadius:14,padding:"36px 28px"}}><div style={{marginBottom:10}}><BrandIcon size={36}/></div><h3 style={{fontFamily:FH,fontWeight:700,fontSize:20,color:C.white}}>We'll be in touch.</h3><p style={{fontSize:14,color:C.slate,marginTop:6}}>Expect a reply within 24 hours.</p></div></Rev>):(<Rev delay={.1}><form name="contact" method="POST" data-netlify="true" netlify-honeypot="bot-field" onSubmit={handleSubmit} style={{display:"flex",flexDirection:"column",gap:14,textAlign:"left"}}><input type="hidden" name="form-name" value="contact"/><p style={{display:"none"}}><label>Don't fill this out: <input name="bot-field"/></label></p><div style={{display:"grid",gridTemplateColumns:mob?"1fr":"1fr 1fr",gap:14}}><input name="name" placeholder="Name" required style={ip("n")} value={f.name} onChange={e=>sF(p=>({...p,name:e.target.value}))} onFocus={()=>sFoc("n")} onBlur={()=>sFoc(null)}/><input name="email" placeholder="Email" type="email" required style={ip("e")} value={f.email} onChange={e=>sF(p=>({...p,email:e.target.value}))} onFocus={()=>sFoc("e")} onBlur={()=>sFoc(null)}/></div><input name="company" placeholder="Company" required style={ip("c")} value={f.company} onChange={e=>sF(p=>({...p,company:e.target.value}))} onFocus={()=>sFoc("c")} onBlur={()=>sFoc(null)}/><textarea name="message" placeholder="Tell us about your account (optional)" rows={3} style={{...ip("m"),resize:"vertical"}} value={f.message} onChange={e=>sF(p=>({...p,message:e.target.value}))} onFocus={()=>sFoc("m")} onBlur={()=>sFoc(null)}/><button type="submit" className="gb" disabled={sending} style={{padding:"14px 28px",borderRadius:10,fontSize:15,fontWeight:700,fontFamily:FB,width:"100%",marginTop:6,opacity:sending?.6:1}}>{sending?"Sending...":"Request a Demo →"}</button></form></Rev>)}</div></section>)}

